frappe.ui.form.on('Issue', {
    custom_expected_resolution_date: function(frm) {
        const expectedResolutionDate = frm.doc.custom_expected_resolution_date;

        // Проверяем статус
        if (frm.doc.status != 'Resolved' && frm.doc.status != 'Closed') {
            if (expectedResolutionDate) {
                // Получаем текущую дату без времени
                const currentDate = new Date(frappe.datetime.now_datetime());
                const currentDateOnly = new Date(currentDate.getFullYear(), currentDate.getMonth(), currentDate.getDate());

                const expectedDate = new Date(expectedResolutionDate);

                // Сравниваем только даты
                frm.set_value('custom_is_overdue', expectedDate < currentDateOnly);
                /*if (expectedDate < currentDateOnly) {
                    frm.set_value('custom_is_overdue', true);
                } else {
                    frm.set_value('custom_is_overdue', false);
                }*/
            } else {
                // Если ожидаемая дата не задана, сбрасываем значение overdue
                frm.set_value('custom_is_overdue', false);
            }
        } else {
            // Если статус 'Resolved' или 'Closed', сбрасываем значение overdue
            frm.set_value('custom_is_overdue', false);
        }
    },
    
    refresh: function(frm) {
        if (frm.doc.custom_is_overdue && frm.doc.status != 'Resolved' && frm.doc.status != 'Closed') {
            frm.dashboard.add_comment(__("Запрос просрочен! Срочно определите и согласуйте с заказчиком новые сроки решения!"),"red",true)
        }
    }
});
